"summary": "The API container's CPU limit is too low, causing throttling and readiness probe failures. Increasing the CPU limit will alleviate throttling.",
"hypotheses": [
  {
    "root_cause_class": "cpu_limit_too_low",
    "summary": "The API container's CPU limit of 0.5 cores is too low, as it's consistently throttled at 64% of its CPU periods.",
    "supporting": ["ev-container_cpu"],
