  },
  {
    "root_cause_class": "insufficient_evidence",
    "summary": "The logs are empty, but this does not contradict CPU throttling; it could indicate other issues like memory pressure, which are not evidenced here.",
    "supporting": ["ev-container_logs_tail"],
    "contradicting": [],
    "missing": ["memory_usage_data"],
    "status": "supported"
  }
],
"proposal": {
  "capability": "deployment.set-resources",
  "target": {
    "group": "apps",
    "kind": "Deployment",
    "namespace": "shop",
    "name": "search",
    "uid": "uid-deployment-search"
  },
  "params": {
    "containers": {
      "api": {
        "requests": {
          "cpu": "250m"
        },
        "limits": {
          "cpu": "750m"
        }
      }
    }
  },
  "expected_effect": "Raising the CPU limit from 0.5 to 0.75 cores should reduce throttling and improve readiness probe success rates.",
  "rationale": "The container is consistently throttled at its current limit (0.5 cores) with 64% throttling ratio and 0.495 CPU usage. Increasing the limit to 0.75 cores (1.5x current) should clear the throttling without affecting other resources.",
  "cited_evidence_ids": ["ev-container_cpu"],
  "cited_predicates": ["throttling_data_available", "cpu_throttled_at_limit", "cpu_usage_near_limit"]
}
}
